/*
 * A257884  Sequence (a(n)) generated by Algorithm (in Comments) with a(1) = 0
 *          and d(1) = 1.
 * https://oeis.org/A257884
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 193, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A257884: 
   a(1) = 0, d(1) = 1.
   For k ≥ 1, let  
        h = the least integer > –a(k) such that h ∉ D(k) and a(k)+h ∉ A(k);
     then a(k+1) = a(k)+h, d(k+1) = h.
   The function returns a(n). */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* --------------------------------------------------------------------- */
/* Simple open‑addressing hash table for arbitrary seq_t values           */
/* --------------------------------------------------------------------- */
typedef struct {
    seq_t *keys;   /* keys */
    bool *used;    /* slot used flag */
    size_t cap;    /* table capacity (power of two) */
    size_t count;  /* number of inserted keys */
} hash_table;

/* hash a seq_t value to size_t (works for signed or unsigned seq_t)   */
static size_t hash_seq_t(seq_t x)
{
    /* mix the high and low bits; works for 64‑bit values              */
    return (size_t)(x ^ (x >> 32) ^ (x >> 16));
}

/* create a hash table with given power‑of‑two capacity                  */
static hash_table *hash_create(size_t cap)
{
    hash_table *t = (hash_table*)malloc(sizeof(hash_table));
    t->cap   = cap;
    t->count = 0;
    t->keys  = (seq_t*)calloc(cap, sizeof(seq_t));
    t->used  = (bool*)calloc(cap, sizeof(bool));
    return t;
}

/* destroy a hash table                                               */
static void hash_destroy(hash_table *t)
{
    free(t->keys);
    free(t->used);
    free(t);
}

/* rehash the table to at least 'newcap' (must be power of two)        */
static void hash_rehash(hash_table *t, size_t newcap)
{
    seq_t *new_keys = (seq_t*)calloc(newcap, sizeof(seq_t));
    bool  *new_used = (bool*)calloc(newcap, sizeof(bool));

    for (size_t i = 0, n = t->cap; i < n; ++i) {
        if (t->used[i]) {
            seq_t k = t->keys[i];
            size_t h = hash_seq_t(k) & (newcap - 1);
            while (new_used[h]) h = (h + 1) & (newcap - 1);
            new_keys[h] = k;
            new_used[h] = true;
        }
    }
    free(t->keys);
    free(t->used);
    t->keys  = new_keys;
    t->used  = new_used;
    t->cap   = newcap;
}

/* insert a key; grow if load factor > 0.5                           */
static void hash_insert(hash_table *t, seq_t key)
{
    if (t->count * 2 >= t->cap) hash_rehash(t, t->cap * 2);
    size_t h = hash_seq_t(key) & (t->cap - 1);
    while (t->used[h]) h = (h + 1) & (t->cap - 1);
    t->keys[h] = key;
    t->used[h] = true;
    ++t->count;
}

/* test whether the key is present                                     */
static bool hash_contains(hash_table *t, seq_t key)
{
    size_t h = hash_seq_t(key) & (t->cap - 1);
    while (t->used[h]) {
        if (t->keys[h] == key) return true;
        h = (h + 1) & (t->cap - 1);
    }
    return false;
}

/* --------------------------------------------------------------------- */
/* Main sequence function                                               */
/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    /* static state */
    static seq_t *a_arr = NULL;   /* array of a values          */
    static seq_t *d_arr = NULL;   /* array of d values          */
    static size_t a_cap = 0, d_cap = 0;
    static size_t a_len = 0, d_len = 0;

    static hash_table *a_hash = NULL;
    static hash_table *d_hash = NULL;

    /* initialise on first call */
    if (!a_len) {
        a_cap = 32;
        d_cap = 32;
        a_arr = (seq_t*)malloc(a_cap * sizeof(seq_t));
        d_arr = (seq_t*)malloc(d_cap * sizeof(seq_t));

        a_hash = hash_create(64);
        d_hash = hash_create(64);

        /* initial values: a(1)=0, d(1)=1 */
        a_arr[0] = (seq_t)0;
        d_arr[0] = (seq_t)1;
        a_len   = 1;
        d_len   = 1;

        hash_insert(a_hash, a_arr[0]);
        hash_insert(d_hash, d_arr[0]);
    }

    /* generate further terms until we have n terms */
    while (a_len < n) {
        seq_t a_k = a_arr[a_len - 1];

        /* find minimal h > -a_k such that h ∉ D and a_k+h ∉ A      */
        seq_t h_start = -(a_k) + (seq_t)1;    /* (-(a_k)+1) */
        seq_t h = h_start;
        for (;;) {
            if (!hash_contains(d_hash, h)) {
                seq_t cand = a_k + h;
                if (!hash_contains(a_hash, cand)) break;
            }
            ++h;
        }

        /* append new a and d */
        if (a_len == a_cap) {
            a_cap *= 2;
            a_arr = (seq_t*)realloc(a_arr, a_cap * sizeof(seq_t));
        }
        if (d_len == d_cap) {
            d_cap *= 2;
            d_arr = (seq_t*)realloc(d_arr, d_cap * sizeof(seq_t));
        }

        a_arr[a_len] = a_k + h;
        d_arr[d_len] = h;

        hash_insert(a_hash, a_arr[a_len]);
        hash_insert(d_hash, h);

        ++a_len;
        ++d_len;
    }

    return a_arr[n - 1];
}
